#include <iostream>
#include <string>
#include <stdexcept>

int main()
{
    std::string s1{"happy"};
    std::string s2{" birthday"};
    std::string s3;

    // Test overloaded equality and relational operators
    std::cout << "s1 is \"" << s1 << "\"; s2 is \"" << s2
              << "\"; s3 is \"" << s3 << "\"\n\n";

    std::cout << "The results of comparing s2 and s1:\n"
              << "s2 == s1 yields " << (s2 == s1 ? "true" : "false") << "\n"
              << "s2 != s1 yields " << (s2 != s1 ? "true" : "false") << "\n"
              << "s2 >  s1 yields " << (s2 > s1 ? "true" : "false")  << "\n"
              << "s2 <  s1 yields " << (s2 < s1 ? "true" : "false")  << "\n"
              << "s2 >= s1 yields " << (s2 >= s1 ? "true" : "false") << "\n"
              << "s2 <= s1 yields " << (s2 <= s1 ? "true" : "false") << "\n\n";

    // Test string member-function empty
    std::cout << "Testing s3.empty():\n";
    if (s3.empty())
    {
        std::cout << "s3 is empty; assigning s1 to s3;\n";
        s3 = s1; // assign s1 to s3
        std::cout << "s3 is \"" << s3 << "\"\n\n";
    }

    // Test overloaded string concatenation operator
    s1 += s2;
    std::cout << "s1 += s2 yields s1 = " << s1 << "\n\n";

    // Test overloaded string concatenation with a C-string literal
    std::cout << "s1 += \" to you\" yields\n";
    s1 += " to you";
    std::cout << "s1 = " << s1 << "\n\n";

    // Test string member function substr
    std::cout << "The substring of s1 starting at location 0 for\n"
              << "14 characters, s1.substr(0, 14), is:\n"
              << s1.substr(0, 14) << "\n\n";

    // Test substr to-end-of-string option
    std::cout << "The substring of s1 starting at\n"
              << "location 15, s1.substr(15), is:\n"
              << s1.substr(15) << "\n\n";

    // Test copy constructor
    std::string s4{s1};
    std::cout << "s4 = " << s4 << "\n\n";

    // Test overloaded copy assignment (=) operator with self-assignment
    std::cout << "assigning s4 to s4\n";
    s4 = s4;
    std::cout << "s4 = " << s4 << "\n\n";

    // Test using overloaded subscript operator to create lvalues
    s1[0] = 'H';
    s1[6] = 'B';
    std::cout << "s1 after s1[0] = 'H' and s1[6] = 'B' is: "
              << s1 << "\n\n";

    // Test subscript out of range with string member function "at"
    try
    {
        std::cout << "Attempt to assign 'd' to s1.at( 30 ) yields:\n";
        s1.at(30) = 'd'; // subscript out of range, throws std::out_of_range
    }
    catch (const std::out_of_range&)
    {
        std::cout << "An exception occurred: subscript out of range\n";
    }

    return 0;
}
